import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import { motion } from 'framer-motion';

// Layout Components
import Navbar from './components/layout/Navbar';
import Sidebar from './components/layout/Sidebar';

// Page Components
import HomePage from './pages/HomePage';
import MatchesPage from './pages/MatchesPage';
import ContestsPage from './pages/ContestsPage';
import TeamBuilderPage from './pages/TeamBuilderPage';
import LeaderboardPage from './pages/LeaderboardPage';
import ProfilePage from './pages/ProfilePage';
import NotificationsPage from './pages/NotificationsPage';
import HistoryPage from './pages/HistoryPage';
import CreateContestPage from './pages/CreateContestPage';

// Providers
import { AuthProvider } from './contexts/AuthContext';
import { SocketProvider } from './contexts/SocketContext';

function App() {
  return (
    <AuthProvider>
      <SocketProvider>
        <Router>
          <div className="min-h-screen bg-gray-50">
            <Navbar />
            <div className="flex">
              <Sidebar />
              <main className="flex-1 lg:ml-64">
                <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.3 }}
                  className="container mx-auto px-4 py-6"
                >
                  <Routes>
                    <Route path="/" element={<HomePage />} />
                    <Route path="/matches" element={<MatchesPage />} />
                    <Route path="/matches/:matchId/contests" element={<ContestsPage />} />
                    <Route path="/contests/:contestId/create-team" element={<TeamBuilderPage />} />
                    <Route path="/contests/:contestId/leaderboard" element={<LeaderboardPage />} />
                    <Route path="/create-contest/:matchId" element={<CreateContestPage />} />
                    <Route path="/profile" element={<ProfilePage />} />
                    <Route path="/notifications" element={<NotificationsPage />} />
                    <Route path="/history" element={<HistoryPage />} />
                  </Routes>
                </motion.div>
              </main>
            </div>
            <Toaster
              position="top-right"
              toastOptions={{
                className: 'bg-white shadow-lg',
                duration: 4000,
              }}
            />
          </div>
        </Router>
      </SocketProvider>
    </AuthProvider>
  );
}

export default App;
